#[no_mangle]
pub unsafe extern "C" fn dimensionality_reduction_lda(input:*const f64,n:usize,output:*mut f64,cap:usize)->i64{
 if input.is_null()||n<16{return -1}let v=std::slice::from_raw_parts(input,n);if v[0]!=2.0||v[2]!=2.0||v[3]!=1.0||v[1].fract()!=0.0||!(4.0..=8.0).contains(&v[1])||n!=4+3*v[1] as usize{return -1}let m=v[1] as usize;let base=4+2*m;let mut x=[0.0;8];let mut y=[0.0;8];let mut labels=[0usize;8];let mut mu=[[0.0;2];2];let mut counts=[0usize;2];
 for i in 0..m{x[i]=v[4+i];y[i]=v[4+m+i];if !x[i].is_finite()||!y[i].is_finite()||x[i].abs()>10000.0||y[i].abs()>10000.0||(v[base+i]!=0.0&&v[base+i]!=1.0){return -1}labels[i]=v[base+i] as usize;counts[labels[i]]+=1;mu[labels[i]][0]+=x[i];mu[labels[i]][1]+=y[i];}if counts[0]<2||counts[1]<2{return -1}for c in 0..2{mu[c][0]/=counts[c] as f64;mu[c][1]/=counts[c] as f64;}
 let(mut a,mut b,mut d)=(0.0,0.0,0.0);for i in 0..m{let c=labels[i];let dx=x[i]-mu[c][0];let dy=y[i]-mu[c][1];a+=dx*dx;b+=dx*dy;d+=dy*dy;}a/=m as f64;b/=m as f64;d/=m as f64;let det=a*d-b*b;if det<=1e-12{return -1}let dx=mu[1][0]-mu[0][0];let dy=mu[1][1]-mu[0][1];let(mut w0,mut w1)=((d*dx-b*dy)/det,(a*dy-b*dx)/det);let norm=(w0*w0+w1*w1).sqrt();if norm<=1e-12{return -1}w0/=norm;w1/=norm;if w0<0.0||(w0.abs()<=1e-14&&w1<0.0){w0=-w0;w1=-w1;}if output.is_null()||cap<m{return -2}let o=std::slice::from_raw_parts_mut(output,m);for i in 0..m{o[i]=w0*x[i]+w1*y[i]}m as i64
}
